#include "cellfit.h"
#include "harness.h"

int main(void) {
    char buf[64];
    uint32_t cp = 0;
    h_init();

    CHECK_INT(cf_decode("\xC3\xA9", 2, &cp), 2);
    CHECK_UINT(cp, 0xE9);
