#include "cellfit.h"
#include "harness.h"

int main(void) {
    char buf[64];
    uint32_t cp = 0;
    h_init();

    CHECK_INT(cf_decode("\xC3\xA9", 2, &cp), 2);
    CHECK_UINT(cp, 0xE9);
    CHECK_INT(cf_width("abc", 3), 3);
    CHECK_INT(cf_fit(buf, sizeof buf, "hello", 5, 10, 1), 5);
    CHECK_STR(buf, "hello");
    CHECK_INT(cf_fit(buf, sizeof buf, "hello world", 11, 8, 1), 10);
    CHECK_STR(buf, "hello w\xE2\x80\xA6");
